begin;
create table public.fx_quotes(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),from_currency text not null,to_currency text not null,numerator bigint not null check(numerator>0 and numerator<=9007199254740991),denominator bigint not null check(denominator>0 and denominator<=9007199254740991),source text not null check(source='https://www.sama.gov.sa/en-US/Currency/FinExc/pages/currency.aspx'),observed_at timestamptz not null,fetched_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null,payload_hash text not null check(payload_hash~'^[a-f0-9]{64}$'),rate_payload jsonb not null,unique(mission_id,id),unique(mission_id,from_currency,to_currency,payload_hash),check(from_currency in('USD','SAR','EUR','GBP','AED')and to_currency in('USD','SAR','EUR','GBP','AED')and from_currency<>to_currency));
create table public.effect_fx_conversions(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),authorization_id uuid not null unique,quote_id uuid not null,original_amount_minor bigint not null,original_currency text not null,mission_amount_minor bigint not null,mission_currency text not null,created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,authorization_id)references public.effect_authorizations(mission_id,id),foreign key(mission_id,quote_id)references public.fx_quotes(mission_id,id));
alter table public.money_ledger add column original_amount_minor bigint,add column original_currency text,add column fx_quote_id uuid references public.fx_quotes(id);
do $$declare t text;begin foreach t in array array['fx_quotes','effect_fx_conversions']loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('create policy mission_scope on public.%I using(private.owns_mission(mission_id))with check(private.owns_mission(mission_id))',t);execute format('create trigger immutable_row before update or delete on public.%I for each row execute function private.immutable_row()',t);execute format('create trigger ledger_revision after insert on public.%I for each row execute function private.record_ledger_revision()',t);end loop;end$$;
grant select on public.fx_quotes,public.effect_fx_conversions to founder_role,lead_role,specialist_role,policy_role;
create function private.fx_minor(p_amount bigint,p_n bigint,p_d bigint)returns bigint language plpgsql immutable set search_path=''as $$declare v numeric;begin if p_amount<0 or p_n<=0 or p_d<=0 then raise exception 'validation: invalid rational FX inputs';end if;v:=ceil(p_amount::numeric*p_n::numeric/p_d::numeric);if v>9007199254740991 then raise exception 'validation: FX result exceeds safe integer';end if;return v::bigint;end$$;
create function private.fx_quote_json(q public.fx_quotes)returns jsonb language sql stable set search_path=''as $$select jsonb_build_object('quoteId',q.id,'from',q.from_currency,'to',q.to_currency,'numerator',q.numerator,'denominator',q.denominator,'source',q.source,'observedAt',to_char(q.observed_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'expiresAt',to_char(q.expires_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))$$;
create function public.record_fx_quote(p_mission uuid,p_from text,p_to text,p_rates jsonb,p_hash text)returns jsonb language plpgsql security definer set search_path=''as $$declare q public.fx_quotes;n numeric;d numeric;observed timestamptz;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);
 if p_from not in('USD','SAR','EUR','GBP','AED')or p_to not in('USD','SAR','EUR','GBP','AED')or p_from=p_to or p_hash!~'^[a-f0-9]{64}$'or p_rates->'from'->>'CurrencyCode'<>p_from||'='or p_rates->'to'->>'CurrencyCode'<>p_to||'='or p_rates->'from'->>'CurrencyDate'is distinct from p_rates->'to'->>'CurrencyDate'or coalesce(p_rates->'from'->>'CurrencyDate','')!~'^\d{4}-\d{2}-\d{2}T00:00:00$'or jsonb_typeof(p_rates->'from'->'CurrencyRate')is distinct from'number'or jsonb_typeof(p_rates->'to'->'CurrencyRate')is distinct from'number'then raise exception 'validation: authoritative FX response correlation failed';end if;
 n:=(p_rates->'from'->>'CurrencyRate')::numeric*100000000;d:=(p_rates->'to'->>'CurrencyRate')::numeric*100000000;
 if n<=0 or d<=0 or n<>trunc(n)or d<>trunc(d)or n>9007199254740991 or d>9007199254740991 or(p_from='SAR'and n<>100000000)or(p_to='SAR'and d<>100000000)then raise exception 'validation: invalid SAMA rational rate';end if;
 observed:=(p_rates->'from'->>'CurrencyDate'||'+03:00')::timestamptz;
 if observed>clock_timestamp()or observed+interval'48 hours'<=clock_timestamp()then raise exception 'validation: FX source date is future or stale';end if;
 insert into public.fx_quotes(mission_id,from_currency,to_currency,numerator,denominator,source,observed_at,expires_at,payload_hash,rate_payload)values(p_mission,p_from,p_to,n::bigint,d::bigint,'https://www.sama.gov.sa/en-US/Currency/FinExc/pages/currency.aspx',observed,observed+interval'48 hours',p_hash,p_rates)on conflict(mission_id,from_currency,to_currency,payload_hash)do nothing returning*into q;
 if q.id is null then select*into strict q from public.fx_quotes where mission_id=p_mission and from_currency=p_from and to_currency=p_to and payload_hash=p_hash;end if;return private.fx_quote_json(q);
end$$;
create function private.fx_for_intent(p_mission uuid,p_intent jsonb)returns jsonb language plpgsql stable set search_path=''as $$declare mission_currency text;payload jsonb;conversion jsonb;q public.fx_quotes;amount bigint;begin
 select currency into strict mission_currency from public.effective_missions where id=p_mission;amount:=coalesce((p_intent->>'amountMinor')::bigint,0);
 if p_intent->>'effectClass'<>'spend'then return jsonb_build_object('amountMinor',amount,'currency',mission_currency);end if;
 select coalesce(content->'payload',content)into strict payload from public.artifact_versions where mission_id=p_mission and id=(p_intent->>'artifactVersionId')::uuid;conversion:=payload->'conversion';
 if p_intent->>'currency'=mission_currency then if conversion is not null then raise exception 'validation: same-currency payment cannot carry a foreign conversion';end if;return jsonb_build_object('amountMinor',amount,'currency',mission_currency);end if;
 perform private.check_version(p_mission,(p_intent->>'artifactVersionId')::uuid);
 select*into q from public.fx_quotes where mission_id=p_mission and id=(conversion->>'quoteId')::uuid;
 if q.id is null or q.from_currency is distinct from p_intent->>'currency'or q.to_currency<>mission_currency or q.expires_at<=clock_timestamp()or conversion-'missionAmountMinor'<>private.fx_quote_json(q)then raise exception 'needs_approval: current exact authoritative FX conversion required';end if;
 if jsonb_typeof(conversion->'missionAmountMinor')is distinct from'number'or(conversion->>'missionAmountMinor')::numeric<>private.fx_minor(amount,q.numerator,q.denominator)then raise exception 'needs_approval: approved mission equivalent differs from rational quote';end if;
 return jsonb_build_object('amountMinor',private.fx_minor(amount,q.numerator,q.denominator),'currency',mission_currency,'quoteId',q.id);
end$$;
create function private.effect_mode(p_mission uuid,p_intent jsonb)returns text language plpgsql stable set search_path=''as $$declare mode text;preferences text[];begin
 select involvement into strict mode from public.missions where id=p_mission;
 select array_agg(value->>'mode')into preferences from(select distinct on(value->>'targetKind',value->>'targetId')value from public.founder_preferences where mission_id=p_mission and kind='help_mode'and(
  (value->>'targetKind'='thread'and exists(select from public.threads t where t.mission_id=p_mission and t.id::text=value->>'targetId'and t.counterparty_id::text=p_intent->>'counterpartyId'))or
  (value->>'targetKind'='commitment'and exists(select from public.commitments c where c.mission_id=p_mission and c.id::text=value->>'targetId'and(c.party_id is null or c.party_id::text=p_intent->>'counterpartyId')))or
  (value->>'targetKind'='activity'and exists(select from public.activity a where a.mission_id=p_mission and a.id::text=value->>'targetId'and(a.run_id::text=p_intent->>'taskId'or(p_intent->>'artifactVersionId')::uuid=any(a.refs)or(p_intent->>'counterpartyId')::uuid=any(a.refs)or exists(select from public.effect_authorizations e where e.mission_id=p_mission and e.id=any(a.refs)and e.intent->>'counterpartyId'=p_intent->>'counterpartyId')))))order by value->>'targetKind',value->>'targetId',created_at desc,id desc)latest;
 if mode='guide'or'guide'=any(preferences)then return'guide';end if;if mode='help'or'help'=any(preferences)then return'help';end if;return'do';
end$$;
create function public.effective_effect_mode(p_mission uuid,p_intent jsonb)returns text language plpgsql stable security definer set search_path=''as $$begin perform private.require_role(array['policy_role']);perform private.assert_mission(p_mission);return private.effect_mode(p_mission,p_intent);end$$;

create or replace function public.reserve_effect(p_mission uuid,p_intent jsonb,p_token_hash text default null)returns jsonb language plpgsql security definer set search_path='' as $$
declare v_existing public.effect_authorizations;v_m public.missions;v_mandate public.mandates;v_approval public.approvals;v_hash text;v_binding jsonb;v_id uuid;v_amount bigint;v_used bigint;v_contacts bigint;v_always boolean;v_conversion jsonb;v_actions bigint;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);perform private.assert_safe_content(p_intent);
  if not(p_intent?&array['missionId','taskId','action','effectClass','counterpartyId','idempotencyKey','mode','sandboxMode'])or p_intent->>'missionId'<>p_mission::text or length(p_intent->>'idempotencyKey')not between 16 and 256 or p_intent->>'effectClass'not in('communicate','spend','publish','bind')then raise exception 'validation: incomplete effect intent'using errcode='22023';end if;
  v_hash:=encode(public.digest(p_intent::text,'sha256'),'hex');
  select * into v_existing from public.effect_authorizations where mission_id=p_mission and idempotency_key=p_intent->>'idempotencyKey';
  if found then if v_existing.intent_hash<>v_hash then raise exception 'invariant_violation: idempotency intent mismatch';end if;return private.authorization_json(v_existing.id,true);end if;
  select * into strict v_m from public.effective_missions where id=p_mission;
  if (p_intent->>'sandboxMode')::boolean<>v_m.sandbox_mode then raise exception 'invariant_violation: environment mismatch';end if;
  if not exists(select from public.counterparties where id=(p_intent->>'counterpartyId')::uuid and founder_id=v_m.founder_id and not opt_out)then raise exception 'invariant_violation: counterparty denied';end if;
  if p_token_hash is null and p_intent->>'effectClass'='communicate'and(p_intent->>'mode'<>'do'or private.effect_mode(p_mission,p_intent)<>'do')then raise exception 'needs_approval: guide or help mode requires founder approval';end if;
  v_amount:=coalesce((p_intent->>'amountMinor')::bigint,0);
  if v_amount<0 then raise exception 'validation: negative amount'using errcode='22023';end if;
  if p_intent->>'effectClass'='spend' then
    if not(p_intent?&array['amountMinor','currency','artifactVersionId','instrumentId'])or(v_amount=0 and not(v_m.sandbox_mode and p_intent->>'action'='store_test_order')) then raise exception 'validation: spend requires positive amount mission currency artifact and instrument (sandbox store_test_order may be zero)'using errcode='22023';end if;
    if not exists(select from public.founder_accounts a where a.id=(p_intent->>'instrumentId')::uuid and a.founder_id=v_m.founder_id and a.status='connected' and not exists(select from public.account_revocations where account_id=a.id))then raise exception 'invariant_violation: instrument revoked or not founder owned';end if;
  end if;
  perform private.check_version(p_mission,(p_intent->>'artifactVersionId')::uuid);
  if p_intent->>'effectClass'='communicate'and private.effect_mode(p_mission,p_intent)<>'do'and not(p_intent?'artifactVersionId')then raise exception 'needs_approval: Guide or Help requires a reviewed immutable draft';end if;
  if p_intent->>'effectClass'='spend'then v_conversion:=private.fx_for_intent(p_mission,p_intent);v_amount:=(v_conversion->>'amountMinor')::bigint;end if;
  v_always:=p_intent->>'effectClass'in('publish','bind')or p_intent->>'action'=any(array['production_order','agreement','publish','legal_filing','mission_end','final_selection','material_terms','refund','payment_refund','store_publish','place_production_order','sign_agreement','submit_legal_filing','end_mission','place_order','accept_agreement','marketing_publish','registration','mission_pivot']);
  if p_token_hash is not null then
    select * into v_approval from public.approvals where mission_id=p_mission and token_hash=p_token_hash for update;
    v_binding:=jsonb_build_object('action',p_intent->>'action','counterpartyId',p_intent->>'counterpartyId','amountMinor',p_intent->'amountMinor','currency',p_intent->'currency','artifactVersionId',p_intent->'artifactVersionId');
    if v_approval.id is null or v_approval.expires_at<=clock_timestamp()or v_approval.binding<>v_binding or exists(select from public.approval_consumptions where approval_id=v_approval.id)or exists(select from public.approval_invalidations where approval_id=v_approval.id)or exists(select from public.decision_supersessions where previous_id=v_approval.decision_id)or exists(select from public.stale_marks where mission_id=p_mission and node_id=v_approval.decision_id)then raise exception 'needs_approval: invalid expired stale or consumed approval';end if;
  elsif v_always then raise exception 'needs_approval: action always requires approval';
  else
    select * into v_mandate from public.mandates where mission_id=p_mission and id=(p_intent->>'mandateId')::uuid for update;
    if v_mandate.id is null or v_mandate.expires_at<=clock_timestamp()or exists(select from public.mandate_revocations where mandate_id=v_mandate.id)or exists(select from public.decision_supersessions where previous_id=v_mandate.decision_id)or exists(select from public.stale_marks where mission_id=p_mission and node_id=v_mandate.decision_id)then raise exception 'needs_approval: no live mandate';end if;
    if not(v_mandate.scope->'actions'?(p_intent->>'action'))or not(v_mandate.scope->'effectClasses'?(p_intent->>'effectClass'))or not(v_mandate.scope->'counterpartyIds'?(p_intent->>'counterpartyId'))or(p_intent?'channel'and not(v_mandate.scope->'channels'?(p_intent->>'channel')))or(p_intent?'purpose'and not(v_mandate.scope->'purposes'?(p_intent->>'purpose')))or(p_intent?'instrumentId'and not(v_mandate.scope->'instrumentIds'?(p_intent->>'instrumentId')))then raise exception 'needs_approval: outside mandate scope';end if;
    if p_intent->>'effectClass'='spend'and(v_amount>v_mandate.ceiling_per or v_mandate.currency<>v_m.currency)then raise exception 'needs_approval: per action ceiling exceeded';end if;
    select coalesce(sum(amount_minor),0),count(*)filter(where(intent->>'newContact')::boolean)into v_used,v_contacts from public.effect_authorizations where mandate_id=v_mandate.id;
    if p_intent->>'effectClass'='spend'and v_mandate.scope?'maxActions'then select count(*)into v_actions from public.effect_authorizations where mandate_id=v_mandate.id and intent->>'effectClass'='spend';if v_actions>=(v_mandate.scope->>'maxActions')::bigint then raise exception 'needs_approval: mandate action count exceeded';end if;end if;
    if v_used+v_amount>v_mandate.ceiling_total then raise exception 'needs_approval: total ceiling exceeded';end if;
    if coalesce((p_intent->>'newContact')::boolean,false)and v_contacts>=coalesce((v_mandate.scope->>'maxNewContacts')::integer,0)then raise exception 'needs_approval: contact ceiling exceeded';end if;
  end if;
  -- Approved budget envelopes are independent of payment authorization.
  if p_intent->>'effectClass'='spend'and exists(select from public.money_ledger where mission_id=p_mission and kind='envelope')and v_amount+(select coalesce(sum(amount_minor),0)from public.effect_authorizations where mission_id=p_mission)>(select sum(amount_minor)from public.money_ledger where mission_id=p_mission and kind='envelope')then raise exception 'needs_approval: budget envelope exceeded';end if;
  insert into public.effect_authorizations(mission_id,intent,intent_hash,idempotency_key,mandate_id,approval_id,amount_minor,sandbox_mode)values(p_mission,p_intent,v_hash,p_intent->>'idempotencyKey',v_mandate.id,v_approval.id,v_amount,v_m.sandbox_mode)returning id into v_id;
  if v_conversion?'quoteId'then insert into public.effect_fx_conversions(mission_id,authorization_id,quote_id,original_amount_minor,original_currency,mission_amount_minor,mission_currency)values(p_mission,v_id,(v_conversion->>'quoteId')::uuid,(p_intent->>'amountMinor')::bigint,p_intent->>'currency',v_amount,v_m.currency);end if;
  if v_approval.id is not null then insert into public.approval_consumptions(mission_id,approval_id,authorization_id)values(p_mission,v_approval.id,v_id);end if;
  insert into public.effect_states(mission_id,authorization_id,status)values(p_mission,v_id,'reserved');
  perform private.audit(p_mission,'planned','Effect authorized and reserved',array[v_id]);return private.authorization_json(v_id,false);
end$$;
create or replace function public.grant_mandate(p_mission uuid,p_decision uuid,p_type text,p_scope jsonb,p_per bigint,p_total bigint,p_expires timestamptz)returns uuid language plpgsql security definer set search_path='' as $$declare v_id uuid;v_currency text;v_approved jsonb;v_count integer;v_key text;begin
  perform private.require_role(array['founder_role','authenticated']);perform private.lock_mission(p_mission);
  if not exists(select from public.decisions where mission_id=p_mission and id=p_decision and kind='mandate')then raise exception 'needs_approval: explicit mandate decision required';end if;
  if not exists(select from public.decision_resolutions where mission_id=p_mission and decision_id=p_decision and response in('approve','choose'))or exists(select from public.decision_supersessions where previous_id=p_decision)then raise exception 'needs_approval: mandate requires active approved decision';end if;
  if p_scope is null or jsonb_typeof(p_scope)<>'object' or not(p_scope?&array['actions','effectClasses','counterpartyIds','channels','purposes','instrumentIds','maxNewContacts'])or p_expires<=now()or p_per>p_total then raise exception 'validation: mandate scope incomplete'using errcode='22023';end if;
  select count(*),min((v.content->'mandate')::text)::jsonb into v_count,v_approved from public.artifact_versions v
    where v.mission_id=p_mission and v.id in(select private.selected_approved_versions(p_mission,p_decision))and v.content?'mandate'
    and (select s.status from public.artifact_statuses s where s.artifact_version_id=v.id order by s.created_at desc,s.id desc limit 1)='approved'
    and not exists(select from public.stale_marks where mission_id=p_mission and node_id=v.id);
  if v_count<>1 or coalesce(jsonb_typeof(v_approved),'')<>'object' or not(v_approved?&array['type','scope','currency','ceilingPer','ceilingTotal','expiresAt'])then raise exception 'needs_approval: mandate needs one selected approved scope version';end if;
  select currency into v_currency from public.effective_missions where id=p_mission;
  if v_approved->>'type'<>p_type or v_approved->>'currency'<>v_currency or p_per<0 or p_total<0
    or p_per>(v_approved->>'ceilingPer')::bigint or p_total>(v_approved->>'ceilingTotal')::bigint
    or p_expires>(v_approved->>'expiresAt')::timestamptz
    or (p_scope->>'maxNewContacts')::integer<0 or (p_scope->>'maxNewContacts')::integer>(v_approved->'scope'->>'maxNewContacts')::integer
    then raise exception 'needs_approval: mandate exceeds selected scope';end if;
  if p_scope?'maxActions'and(jsonb_typeof(p_scope->'maxActions')is distinct from'number'or(p_scope->>'maxActions')::numeric<1 or(p_scope->>'maxActions')::numeric<>trunc((p_scope->>'maxActions')::numeric)or(p_scope->>'maxActions')::numeric>9007199254740991)then raise exception 'validation: maxActions must be a positive safe integer';end if;
  if v_approved->'scope'?'maxActions'and(not(p_scope?'maxActions')or(p_scope->>'maxActions')::numeric>(v_approved->'scope'->>'maxActions')::numeric)then raise exception 'needs_approval: mandate action count widened';end if;
  foreach v_key in array array['actions','effectClasses','counterpartyIds','channels','purposes','instrumentIds']loop
    if coalesce(jsonb_typeof(p_scope->v_key),'')<>'array' or coalesce(jsonb_typeof(v_approved->'scope'->v_key),'')<>'array' or not((p_scope->v_key) <@ ((v_approved->'scope')->v_key))then raise exception 'needs_approval: mandate scope widened';end if;
  end loop;
  insert into public.mandates(mission_id,decision_id,type,scope,ceiling_per,ceiling_total,currency,expires_at)values(p_mission,p_decision,p_type,p_scope,p_per,p_total,v_currency,p_expires)returning id into v_id;return v_id;
end$$;
create or replace function public.begin_effect(p_mission uuid,p_authorization uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare v_a public.effect_authorizations;v_status text;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);
  select * into strict v_a from public.effect_authorizations where mission_id=p_mission and id=p_authorization for update;
  select status into v_status from public.effect_states where authorization_id=p_authorization order by created_at desc,id desc limit 1;
  if v_a.mandate_id is not null and(exists(select from public.mandate_revocations where mandate_id=v_a.mandate_id)or exists(select from public.mandates m where m.id=v_a.mandate_id and(m.expires_at<=clock_timestamp()or exists(select from public.decision_supersessions where previous_id=m.decision_id)or exists(select from public.stale_marks where mission_id=p_mission and node_id=m.decision_id))))then raise exception 'invariant_violation: mandate revoked or expired';end if;
  if v_a.approval_id is not null and(exists(select from public.approval_invalidations where approval_id=v_a.approval_id)or exists(select from public.approvals where id=v_a.approval_id and expires_at<=clock_timestamp()))then raise exception 'needs_approval: approval invalidated or expired';end if;
  perform private.check_version(p_mission,(v_a.intent->>'artifactVersionId')::uuid);
  if v_a.intent->>'effectClass'='communicate'and private.effect_mode(p_mission,v_a.intent)<>'do'and(v_a.approval_id is null or not(v_a.intent?'artifactVersionId'))then raise exception 'needs_approval: current Guide or Help requires reviewed draft approval';end if;
  if v_a.intent->>'effectClass'='spend'then perform private.fx_for_intent(p_mission,v_a.intent);end if;
  perform 1 from public.founder_accounts where id=(v_a.intent->>'instrumentId')::uuid for share;
  if exists(select from public.account_revocations where account_id=(v_a.intent->>'instrumentId')::uuid)then raise exception 'invariant_violation: instrument revoked';end if;
  if v_status<>'reserved' then return private.authorization_json(p_authorization,true);end if;
  insert into public.effect_states(mission_id,authorization_id,status)values(p_mission,p_authorization,'started');return private.authorization_json(p_authorization,false);
end$$;
create or replace function public.prepare_payment(p_mission uuid,p_authorization uuid,p_provider text)returns uuid language plpgsql security definer set search_path='' as $$declare v_a public.effect_authorizations;v_id uuid;v_fx public.effect_fx_conversions;v_q public.fx_quotes;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select * into strict v_a from public.effect_authorizations where mission_id=p_mission and id=p_authorization;
  if v_a.intent->>'effectClass'<>'spend' then raise exception 'invariant_violation: payment requires spend authorization';end if;
  insert into public.payments(mission_id,authorization_id,provider,payee_id,instrument_id,amount_minor,currency,purpose,artifact_version_id,sandbox_mode)values(p_mission,p_authorization,p_provider,(v_a.intent->>'counterpartyId')::uuid,(v_a.intent->>'instrumentId')::uuid,(v_a.intent->>'amountMinor')::bigint,v_a.intent->>'currency',coalesce(v_a.intent->>'purpose',v_a.intent->>'action'),(v_a.intent->>'artifactVersionId')::uuid,v_a.sandbox_mode)on conflict(authorization_id)do nothing returning id into v_id;
  if v_id is null then select id into v_id from public.payments where authorization_id=p_authorization;return v_id;end if;
  insert into public.payment_states(mission_id,payment_id,state)values(p_mission,v_id,'approved');
  select*into v_fx from public.effect_fx_conversions where authorization_id=v_a.id;select*into v_q from public.fx_quotes where id=v_fx.quote_id;
  insert into public.money_ledger(mission_id,kind,amount_minor,currency,basis,envelope,ref_id,sandbox_mode,original_amount_minor,original_currency,fx_quote_id,fx_rate,fx_source,fx_at)values(p_mission,'committed',v_a.amount_minor,coalesce(v_fx.mission_currency,v_a.intent->>'currency'),'accepted',coalesce(v_a.intent->>'purpose','general'),v_id,v_a.sandbox_mode,(v_a.intent->>'amountMinor')::bigint,v_a.intent->>'currency',v_q.id,v_q.numerator::numeric/v_q.denominator::numeric,v_q.source,v_q.observed_at);return v_id;
end$$;
create or replace function public.confirm_payment(p_mission uuid,p_payment uuid,p_receipt uuid,p_confirmation uuid)returns uuid language plpgsql security definer set search_path='' as $$declare v_p public.payments;v_id uuid;v_fx public.effect_fx_conversions;v_q public.fx_quotes;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select * into strict v_p from public.payments where mission_id=p_mission and id=p_payment for update;
  if not exists(select from public.provider_receipts where id=p_receipt and mission_id=p_mission and authorization_id=v_p.authorization_id and sandbox_mode=v_p.sandbox_mode and provider=v_p.provider)then raise exception 'invariant_violation: payment receipt mismatch';end if;
  if not exists(select from public.events e join public.provider_receipts r on r.id=p_receipt and r.mission_id=e.mission_id where e.id=p_confirmation and e.mission_id=p_mission and e.signature_verified and e.provider=v_p.provider and e.type in('payment.captured','payment.verified_poll')and(e.payload->>'paymentId')=p_payment::text and(e.payload->>'amountMinor')::bigint=v_p.amount_minor and e.payload->>'currency'=v_p.currency and(e.payload->>'sandboxMode')::boolean=v_p.sandbox_mode and e.payload->>'payeeId'=v_p.payee_id::text and e.payload->>'providerReference'=r.provider_reference and e.payload->>'orderId'=r.data->>'orderId'and length(e.payload->>'orderId')>0)then raise exception 'invariant_violation: verified payment confirmation required';end if;
  if exists(select from public.payment_states where payment_id=p_payment and state='captured')then select id into v_id from public.payment_states where payment_id=p_payment and state='captured';return v_id;end if;
  insert into public.payment_states(mission_id,payment_id,state,receipt_id,confirmation_event_id)values(p_mission,p_payment,'captured',p_receipt,p_confirmation)returning id into v_id;
  select*into v_fx from public.effect_fx_conversions where authorization_id=v_p.authorization_id;select*into v_q from public.fx_quotes where id=v_fx.quote_id;
  insert into public.money_ledger(mission_id,kind,amount_minor,currency,basis,envelope,ref_id,receipt_id,confirmation_event_id,sandbox_mode,original_amount_minor,original_currency,fx_quote_id,fx_rate,fx_source,fx_at)values(p_mission,'spent',coalesce(v_fx.mission_amount_minor,v_p.amount_minor),coalesce(v_fx.mission_currency,v_p.currency),'accepted',v_p.purpose,p_payment,p_receipt,p_confirmation,v_p.sandbox_mode,v_p.amount_minor,v_p.currency,v_q.id,v_q.numerator::numeric/v_q.denominator::numeric,v_q.source,v_q.observed_at);
  insert into public.outbox(mission_id,type,payload)values(p_mission,'payment.captured',jsonb_build_object('paymentId',p_payment));return v_id;
end$$;
create or replace function public.register_payment_refund(p_mission uuid,p_receipt uuid)returns uuid language plpgsql security definer set search_path=''as $$declare r public.provider_receipts;a public.effect_authorizations;p public.payments;v_id uuid;v_sum bigint;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select *into strict r from public.provider_receipts where mission_id=p_mission and id=p_receipt and provider='paypal'and operation='payment_refund';select *into strict a from public.effect_authorizations where mission_id=p_mission and id=r.authorization_id and approval_id is not null;
  select pmt.*into strict p from public.payments pmt join public.provider_receipts original on original.authorization_id=pmt.authorization_id where pmt.mission_id=p_mission and pmt.provider='paypal'and original.provider_reference=r.data->>'captureId'and original.data->>'orderId'=r.data->>'orderId'and pmt.payee_id=(a.intent->>'counterpartyId')::uuid and pmt.currency=a.intent->>'currency'and pmt.sandbox_mode=r.sandbox_mode;
  select id into v_id from public.payment_refunds where mission_id=p_mission and receipt_id=p_receipt;if v_id is not null then return v_id;end if;
  select coalesce(sum(amount_minor),0)into v_sum from public.payment_refunds where payment_id=p.id;if (a.intent->>'amountMinor')::bigint<=0 or (a.intent->>'amountMinor')::bigint+v_sum>p.amount_minor then raise exception 'invariant_violation: refund exceeds original payment';end if;
  insert into public.payment_refunds(mission_id,payment_id,authorization_id,receipt_id,provider_refund_id,amount_minor,currency,sandbox_mode)values(p_mission,p.id,a.id,r.id,r.provider_reference,(a.intent->>'amountMinor')::bigint,p.currency,p.sandbox_mode)returning id into v_id;return v_id;
end$$;
create or replace function public.confirm_payment_refund(p_mission uuid,p_refund uuid,p_event uuid)returns uuid language plpgsql security definer set search_path=''as $$declare f public.payment_refunds;p public.payments;r public.provider_receipts;v_id uuid;v_total bigint;v_fx public.effect_fx_conversions;v_q public.fx_quotes;v_booked bigint;v_prior bigint;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select *into strict f from public.payment_refunds where mission_id=p_mission and id=p_refund;select *into strict p from public.payments where mission_id=p_mission and id=f.payment_id;select *into strict r from public.provider_receipts where mission_id=p_mission and id=f.receipt_id;
  if not exists(select from public.events e where e.id=p_event and e.mission_id=p_mission and e.provider='paypal'and e.signature_verified and e.type in('payment.refunded','payment.refund_verified_poll')and e.payload->>'refundId'=f.id::text and e.payload->>'providerReference'=f.provider_refund_id and e.payload->>'orderId'=r.data->>'orderId'and e.payload->>'captureId'=r.data->>'captureId'and e.payload->>'payeeId'=p.payee_id::text and(e.payload->>'amountMinor')::bigint=f.amount_minor and e.payload->>'currency'=f.currency and(e.payload->>'sandboxMode')::boolean=f.sandbox_mode)then raise exception 'invariant_violation: exact verified refund confirmation required';end if;
  if not exists(select from public.payment_states where payment_id=p.id and state='captured')then raise exception 'invariant_violation: original payment settlement must be reconciled first';end if;
  select id into v_id from public.refund_confirmations where refund_id=f.id;if v_id is not null then return v_id;end if;
  insert into public.refund_confirmations(mission_id,refund_id,event_id)values(p_mission,f.id,p_event)returning id into v_id;
  select*into v_fx from public.effect_fx_conversions where authorization_id=p.authorization_id;select*into v_q from public.fx_quotes where id=v_fx.quote_id;v_booked:=f.amount_minor;
  if v_q.id is not null then select coalesce(sum(x.amount_minor),0)into v_total from public.payment_refunds x join public.refund_confirmations c on c.refund_id=x.id where x.payment_id=p.id;select coalesce(sum(amount_minor),0)into v_prior from public.money_ledger where mission_id=p_mission and ref_id=p.id and kind='refund';v_booked:=case when v_total=p.amount_minor then v_fx.mission_amount_minor-v_prior else floor(f.amount_minor::numeric*v_q.numerator/v_q.denominator)::bigint end;end if;
  insert into public.money_ledger(mission_id,kind,amount_minor,currency,basis,envelope,ref_id,receipt_id,confirmation_event_id,sandbox_mode,original_amount_minor,original_currency,fx_quote_id,fx_rate,fx_source,fx_at)values(p_mission,'refund',v_booked,coalesce(v_fx.mission_currency,f.currency),'accepted',p.purpose,p.id,f.receipt_id,p_event,f.sandbox_mode,f.amount_minor,f.currency,v_q.id,v_q.numerator::numeric/v_q.denominator::numeric,v_q.source,v_q.observed_at);
  select coalesce(sum(x.amount_minor),0)into v_total from public.payment_refunds x join public.refund_confirmations c on c.refund_id=x.id where x.payment_id=p.id;if v_total=p.amount_minor then insert into public.payment_states(mission_id,payment_id,state,receipt_id,confirmation_event_id)values(p_mission,p.id,'refunded',f.receipt_id,p_event);end if;
  insert into public.outbox(mission_id,type,payload)values(p_mission,'payment.refunded',jsonb_build_object('paymentId',p.id,'refundId',f.id));return v_id;
end$$;
create or replace function public.voice_output_allowed(p_mission uuid,p_session uuid)returns boolean language plpgsql security definer set search_path=''as $$declare v public.voice_sessions;v_authority public.effect_authorizations;begin
  perform private.require_role(array['voice_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);select *into strict v from public.voice_sessions where id=p_session and mission_id=p_mission;
  if exists(select from public.voice_session_events where session_id=p_session and kind in('ended','optout'))or exists(select from public.counterparty_optouts where counterparty_id=v.counterparty_id)or exists(select from public.counterparties where id=v.counterparty_id and opt_out)or exists(select from public.mandate_revocations where mandate_id in(v.mandate_id,v.outreach_mandate_id))or(v.mandate_id is not null and not exists(select from public.mandates m where m.id=v.mandate_id and m.expires_at>clock_timestamp()and not exists(select from public.stale_marks where node_id=m.decision_id)))or(v.outreach_mandate_id is not null and not exists(select from public.mandates m where m.id=v.outreach_mandate_id and m.expires_at>clock_timestamp()and not exists(select from public.stale_marks where node_id=m.decision_id)))then return false;end if;
  select *into v_authority from public.effect_authorizations a where a.mission_id=p_mission and a.intent->>'taskId'=v.task_id::text and a.intent->>'action'='send_message'and a.intent->>'channel'='voice'and a.intent->>'counterpartyId'=v.counterparty_id::text;
  if v_authority.id is null or exists(select from public.approval_invalidations where approval_id=v_authority.approval_id)then return false;end if;
  perform private.check_version(p_mission,(v_authority.intent->>'artifactVersionId')::uuid);
  perform 1 from public.founder_accounts a join private.provider_credentials c on c.account_id=a.id where c.ref in(v.twilio_ref,v.openai_ref)for share of a;
  if exists(select from public.effect_authorizations a where a.mission_id=p_mission and a.intent->>'taskId'=v.task_id::text and a.intent->>'channel'='voice'and private.effect_mode(p_mission,a.intent)<>'do'and(a.approval_id is null or not(a.intent?'artifactVersionId')))then return false;end if;
  if exists(select from public.account_revocations r join private.provider_credentials c on c.account_id=r.account_id where c.ref in(v.twilio_ref,v.openai_ref))then return false;end if;return true;
end$$;
revoke all on function private.fx_minor(bigint,bigint,bigint),private.fx_quote_json(public.fx_quotes),private.fx_for_intent(uuid,jsonb),private.effect_mode(uuid,jsonb)from public;
revoke all on function public.record_fx_quote(uuid,text,text,jsonb,text),public.effective_effect_mode(uuid,jsonb)from public;
grant execute on function public.record_fx_quote(uuid,text,text,jsonb,text),public.effective_effect_mode(uuid,jsonb)to policy_role;
commit;
